SELECT concat_ws('|',
  (SELECT coalesce(md5(string_agg(product_id::text||':'||outlet_id::text||':'||coalesce(effective_quantity::text,'NULL')||':'||balance_version,
    E'\n' ORDER BY outlet_id,product_id)),'EMPTY') FROM public.stock_balance_projection),
  (SELECT coalesce(md5(string_agg(id::text||':'||status||':'||draft_revision,E'\n' ORDER BY id)),'EMPTY') FROM public.purchase_receipts),
  (SELECT coalesce(md5(string_agg(id::text||':'||receipt_id::text||':'||product_id::text||':'||accepted_quantity||':'||bonus_quantity,
    E'\n' ORDER BY receipt_id,product_id)),'EMPTY') FROM public.purchase_receipt_items),
  (SELECT coalesce(md5(string_agg(id::text||':'||receipt_id::text||':'||event_type||':'||coalesce(request_id::text,''),
    E'\n' ORDER BY id)),'EMPTY') FROM public.purchase_receipt_events),
  (SELECT coalesce(md5(string_agg(id::text||':'||operation_request_id::text,E'\n' ORDER BY id)),'EMPTY') FROM public.stock_movement_batches),
  (SELECT coalesce(md5(string_agg(id::text||':'||product_id::text||':'||quantity_delta::text||':'||source_event_key,
    E'\n' ORDER BY id)),'EMPTY') FROM public.stock_movements),
  (SELECT coalesce(md5(string_agg(product_id::text||':'||outlet_id::text||':'||coalesce(quantity::text,'NULL'),
    E'\n' ORDER BY outlet_id,product_id)),'EMPTY') FROM public.product_inventory),
  (SELECT coalesce(md5(string_agg(product_id::text||':'||outlet_id::text||':'||coalesce(hpp::text,'NULL')||':'||coalesce(source_import_row_id::text,''),
    E'\n' ORDER BY outlet_id,product_id)),'EMPTY') FROM public.product_costs),
  (SELECT coalesce(md5(string_agg(product_id::text||':'||outlet_id::text||':'||coalesce(hpp::text,'NULL')||':'||effective_at::text,
    E'\n' ORDER BY outlet_id,product_id,effective_at,id)),'EMPTY') FROM public.product_cost_history),
  (SELECT coalesce(md5(string_agg(outlet_id::text||':'||product_id::text||':'||physical_quantity::text||':'||valued_quantity::text||':'||
      provisional_quantity::text||':'||unvalued_quantity::text||':'||coalesce(inventory_value::text,'NULL')||':'||cost_version,
    E'\n' ORDER BY outlet_id,product_id)),'EMPTY') FROM public.inventory_cost_projections),
  (SELECT coalesce(md5(string_agg(id::text||':'||receipt_id::text||':'||receipt_item_identity::text||':'||revision::text||':'||evidence_kind::text,
    E'\n' ORDER BY id)),'EMPTY') FROM public.purchase_receipt_acquisition_estimate_revisions),
  (SELECT coalesce(md5(string_agg(id::text||':'||receipt_id::text||':'||receipt_item_id::text||':'||product_id::text||':'||event_type::text||':'||cost_version_after::text,
    E'\n' ORDER BY id)),'EMPTY') FROM public.inventory_cost_events),
  (SELECT coalesce(md5(string_agg(id::text||':'||outlet_id::text||':'||operation_request_id::text,E'\n' ORDER BY id)),'EMPTY')
    FROM public.inventory_cost_event_batches),
  (SELECT coalesce(md5(string_agg(request_id::text||':'||operation_key||':'||target_key||':'||payload_hash||':'||coalesce(result::text,''),
    E'\n' ORDER BY request_id)),'EMPTY') FROM public.stock_operation_requests),
  (SELECT coalesce(md5(string_agg(request_id::text||':'||actor_id::text||':'||operation_key||':'||target_key||':'||payload_hash||':'||coalesce(result::text,''),
    E'\n' ORDER BY request_id)),'EMPTY') FROM public.inventory_cost_operation_requests),
  (SELECT coalesce(md5(string_agg(outlet_id::text||':'||status::text,E'\n' ORDER BY outlet_id)),'EMPTY') FROM public.inventory_costing_outlet_authority));
